    if (bucket == 0) {
        std_meta.egress_spec = port;
        port_register.write((bit<32>)hdr.nsh.spi, (bit<32>)port);
    } else if (bucket == 1) {
        std_meta.egress_spec = port + 1;
        port_register.write((bit<32>)hdr.nsh.spi, (bit<32>)port + 1);
    } else if (bucket == 2) {
        std_meta.egress_spec = port + 2;
        port_register.write((bit<32>)hdr.nsh.spi, (bit<32>)port + 2);
    } else {
        std_meta.egress_spec = port + 3;
        port_register.write((bit<32>)hdr.nsh.spi, (bit<32>)port + 3);
    }
    hdr.nsh.si = hdr.nsh.si - 1;
