action send_frame(bit<9> port, bit<48> packet_cost) {
    bit<48> tokens;
    bit<32> last_update;
    bit<32> current_time = (bit<32>)std_meta.ingress_global_timestamp;
    bit<32> elapsed_time = current_time - last_update;
    bit<48> recharge = (bit<48>)elapsed_time * 1000;
    tb_tokens.read(tokens, (bit<32>)hdr.nsh.spi);
    tb_last_update.read(last_update, (bit<32>)hdr.nsh.spi);
    tokens = tokens + recharge;
    if (tokens >= packet_cost) {
        tb_tokens.write((bit<32>)hdr.nsh.spi, tokens - packet_cost);
        tb_last_update.write((bit<32>)hdr.nsh.spi, current_time);
        hdr.nsh.si = hdr.nsh.si + 1;
        hdr.nsh.si = hdr.nsh.si - 1;
        std_meta.egress_spec = port;
    } else {
        tb_tokens.write((bit<32>)hdr.nsh.spi, tokens);
        tb_last_update.write((bit<32>)hdr.nsh.spi, current_time);
        hdr.nsh.si = hdr.nsh.si - 1;
    }
}

