        if (hdr.ipv4.isValid()) {
            // Implement forwarding logic here
        }
    }

    action set_packet() {
        // Send the packet to port 3 for Ethernet
        std_meta.egress_spec = 3;
        hdr.nsh.si = hdr.nsh.si - 1;
    }

    action set_frame() {
        mark_to_drop(std_meta);
    }

    table nsh_map {
        key = {
            hdr.nsh.next_proto: exact;
        }
        actions = { exec_pkt; set_packet; NoAction; }
