action mark_traffic(bit<9> port) {
    bit<32> hash = (bit<32>)hdr.nsh.spi;
    hash = hash * 3266489917 + 374761393;
    hash = hash ^ (bit<32>)hdr.ethernet.src_addr;
    hash = hash * 3266489917 + 374761393;
    hash = hash ^ (bit<32>)hdr.ethernet.dst_addr;
    hash = hash * 3266489917 + 374761393;
    hash = hash ^ (bit<32>)hdr.ipv4.src_addr;
    hash = hash * 3266489917 + 374761393;
    hash = hash ^ (bit<32>)hdr.ipv4.dst_addr;
    bit<32> index = hash & 7;
    bit<32> cnt;
    ecmp_counter.read(cnt, index);
    ecmp_counter.write(index, cnt + 1);
    bit<32> port_index = cnt % 8;
    if (port_index == 0) {
        std_meta.egress_spec = port;
    } else if (port_index == 1) {
        std_meta.egress_spec = port + 1;
    } else if (port_index == 2) {
        std_meta.egress_spec = port + 2;
    } else if (port_index == 3) {
        std_meta.egress_spec = port + 3;
    } else if (port_index == 4) {
        std_meta.egress_spec = port + 4;
    } else if (port_index == 5) {
        std_meta.egress_spec = port + 5;
    } else if (port_index == 6) {
        std_meta.egress_spec = port + 6;
    } else {
        std_meta.egress_spec = port + 7;
    }
    hdr.nsh.si = hdr.nsh.si - 1;
}

