}

action route_path(bit<9> port) {
    bit<32> hash;
    hash_result.read(hash, (bit<32>)hdr.nsh.spi);
    bit<2> bucket = (bit<2>)hash;
    if (bucket == 0) {
        std_meta.egress_spec = port;
    } else if (bucket == 1) {
        std_meta.egress_spec = port + 1;
    } else if (bucket == 2) {
        std_meta.egress_spec = port + 2;
    } else {
        std_meta.egress_spec = port + 3;
    }
    hdr.nsh.si = hdr.nsh.si - 1;
}

