control MyIngress(inout headers_t hdr, inout metadata_t meta,
                  inout standard_metadata_t std_meta) {

    action fwd_path() { mark_to_drop(std_meta); }

    action exec_packet(bit<9> port) {
        std_meta.egress_spec = port;
        hdr.nsh.si = hdr.nsh.si - 1;
    }

    action process_pkt(bit<9> port) {
        std_meta.egress_spec = port;
        hdr.nsh.si = hdr.nsh.si - 1; // Decrement SI at each hop
    }

    table forward_lookup {
        key = {
            hdr.ethernet.ether_type: exact;
        }
        actions = { exec_packet; process_pkt; NoAction; }
        size = 256;
        default_action = NoAction();
    }

    apply {
        if (hdr.ethernet.isValid()) {
            forward_lookup.apply();
        } else {
            fwd_path();
        }
    }
}

